import os
from azure.identity import DefaultAzureCredential
from azure.ai.projects import AIProjectClient

ENDPOINT = os.environ["FOUNDRY_PROJECT_ENDPOINT"]
AGENT_NAME = os.environ.get("FOUNDRY_AGENT_NAME", "expenses-agent")


def print_citations(response):
    """Muestra las anotaciones de cita (web, archivos) si las hay."""
    for item in response.output:
        if item.type != "message":
            continue
        for part in item.content:
            if part.type == "output_text":
                for ann in part.annotations or []:
                    source = getattr(ann, "url", None) or getattr(ann, "filename", None)
                    print(f"   [cita] {ann.type}: {source}")


def main():
    project = AIProjectClient(endpoint=ENDPOINT, credential=DefaultAzureCredential())
    openai = project.get_openai_client()
    agent_ref = {"agent_reference": {"name": AGENT_NAME, "type": "agent_reference"}}

    conversation = openai.conversations.create()
    print(f"Conversación {conversation.id} con el agente '{AGENT_NAME}'. Escribe 'salir' para terminar.")
    try:
        while True:
            question = input("\nTú: ").strip()
            if not question:
                continue
            if question.lower() in ("salir", "exit", "quit"):
                break
            response = openai.responses.create(
                conversation=conversation.id,
                input=question,
                extra_body=agent_ref,
            )
            print(f"Agente: {response.output_text}")
            print_citations(response)
    finally:
        openai.conversations.delete(conversation_id=conversation.id)
        print("Conversación eliminada.")


if __name__ == "__main__":
    main()
